"use client";

import * as React from "react";
import type { Locale } from "date-fns";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import {
  useFilterTokens,
  type FilterSchema,
  type FilterTokensProps,
} from "filter-tokens";
import { Trigger } from "./parts/trigger";
import { Header } from "./parts/header";
import { Listbox } from "./parts/listbox";
import { Panels } from "./parts/panels";

/* ─── Types ────────────────────────────────────────────────────────────────── */

type FilterTokensComponentProps<T extends FilterSchema> = FilterTokensProps<T> &
  Omit<React.ComponentProps<"div">, "onChange"> & {
    dateLocale?: Locale;
  };

/* ─── FilterTokens ─────────────────────────────────────────────────────────── */

function FilterTokens<const T extends FilterSchema>({
  filters,
  value,
  onChange,
  placeholder = "Filter...",
  className,
  disabled,
  dateLocale,
  messages,
  ...props
}: FilterTokensComponentProps<T>) {
  const ft = useFilterTokens({
    filters,
    value,
    onChange,
    placeholder,
    locale: dateLocale?.code,
    messages,
  });
  const listboxId = React.useId();
  const popoverContentId = React.useId();

  const state = ft.dropdown.state;
  const isInput = state.mode === "input";
  const inputType = isInput ? state.inputType : null;
  const activeCategory =
    state.mode === "values" || state.mode === "input" ? state.category : null;
  const isTextEntry = inputType === "text";
  const isDateEntry = inputType === "date";
  const isPanelMode = inputType === "date" || inputType === "number";

  const activeDef = activeCategory
    ? (filters as FilterSchema)[activeCategory]
    : null;
  const activeLabel = activeDef?.label ?? null;
  const isMultiSelect =
    activeDef?.type === "select" && activeDef.multi === true;

  return (
    <PopoverPrimitive.Root
      open={ft.dropdown.isOpen}
      onOpenChange={(open) => { if (!open) ft.dropdown.close(); }}
      modal={false}
    >
      <PopoverPrimitive.Anchor asChild>
        <div data-slot="filter-tokens" {...props}>
          <Trigger
            ft={ft}
            listboxId={listboxId}
            disabled={disabled}
            className={className}
          />
        </div>
      </PopoverPrimitive.Anchor>

      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Content
          id={popoverContentId}
          data-slot="filter-tokens-dropdown"
          data-mode={state.mode}
          data-input-type={inputType ?? undefined}
          align="start"
          sideOffset={4}
          className="z-50 max-w-[480px] min-w-(--radix-popover-trigger-width) rounded-lg border border-border bg-popover p-0 text-popover-foreground shadow-lg outline-none"
          onOpenAutoFocus={(e) => e.preventDefault()}
          onCloseAutoFocus={(e) => e.preventDefault()}
          onInteractOutside={(e) => {
            // The combobox input lives in the trigger area, not in the popover
            // content. When focus moves to it (after a token click or option
            // selection), Radix would otherwise treat that as an outside
            // interaction and close. Keep it open for any interaction inside
            // our trigger surface.
            const target = e.target as Element | null;
            if (target?.closest?.('[data-slot="filter-tokens-trigger"]')) {
              e.preventDefault();
            }
          }}
          onEscapeKeyDown={(e) => {
            // Radix's escape listener fires in document capture phase, so it
            // runs *before* the hook's handleKeyDown (which is the input's
            // onKeyDown bubble). React 19 flushes setState between phases,
            // which means the hook would see the *new* mode and advance a
            // second time (values → categories → close).
            //
            // To make ESC behave correctly:
            //  - In sub-modes (values / input): goBack here and preventDefault
            //    so Radix doesn't dismiss. The hook then short-circuits
            //    because e.defaultPrevented === true.
            //  - In categories mode: do nothing here — let Radix's default
            //    dismiss path run (calls onOpenChange(false)), which closes.
            if (state.mode === "values" || state.mode === "input") {
              e.preventDefault();
              ft.dropdown.goBack();
            }
          }}
        >
          {activeLabel && (
            <Header
              activeLabel={activeLabel}
              isDateEntry={isDateEntry}
              onBack={ft.dropdown.goBack}
              messages={ft.messages}
            />
          )}

          {!isPanelMode && (
            <Listbox
              ft={ft}
              listboxId={listboxId}
              activeLabel={activeLabel}
              isMultiSelect={isMultiSelect}
              isTextEntry={isTextEntry}
            />
          )}

          {isPanelMode && (
            <Panels
              ft={ft}
              filters={filters}
              value={value}
              dateLocale={dateLocale}
            />
          )}
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
}

/* ─── Exports ──────────────────────────────────────────────────────────────── */

export { FilterTokens };
export type { FilterTokensComponentProps };

"use client";

import * as React from "react";
import { XIcon } from "lucide-react";
import type { FilterSchema, FilterTokensReturn } from "filter-tokens";
import { cn } from "@/lib/utils";
import { Token } from "./token";

export interface TriggerProps<T extends FilterSchema> {
  ft: FilterTokensReturn<T>;
  /**
   * ID of the listbox element rendered inside the popover content.
   * Used for `aria-controls` and to compute the highlighted option ID
   * for `aria-activedescendant`.
   */
  listboxId: string;
  disabled?: boolean;
  className?: string;
}

export function Trigger<T extends FilterSchema>({
  ft,
  listboxId,
  disabled,
  className,
}: TriggerProps<T>) {
  const tokenRefs = React.useRef<(HTMLSpanElement | null)[]>([]);

  const state = ft.dropdown.state;
  const isPanelMode =
    state.mode === "input" &&
    (state.inputType === "date" || state.inputType === "number");

  // When the popover opens (via token click, keyboard, or programmatic open()),
  // make sure focus lands on our outer input — except in date/number entry
  // where the panel manages its own focus, and except when focus has
  // intentionally moved to a token (ArrowLeft token nav). Without the
  // token-aware guard, the rAF would yank focus back to the input every
  // time mode changes.
  React.useEffect(() => {
    if (ft.dropdown.isOpen && !isPanelMode) {
      requestAnimationFrame(() => {
        const active = document.activeElement;
        const onToken = active?.closest?.(
          '[data-slot="filter-tokens-token"]',
        );
        if (onToken) return;
        ft.inputProps.ref.current?.focus();
      });
    }
  }, [ft.dropdown.isOpen, state.mode, isPanelMode, ft.inputProps.ref]);

  const highlightedItem =
    ft.dropdown.highlightedIndex >= 0
      ? ft.dropdown.items[ft.dropdown.highlightedIndex]
      : null;
  const activeDescendantId =
    ft.dropdown.isOpen && highlightedItem
      ? `${listboxId}-item-${highlightedItem.key}`
      : undefined;

  function handleWrapperMouseDown(e: React.MouseEvent<HTMLDivElement>) {
    if (disabled) return;
    const target = e.target as HTMLElement;
    if (
      target.closest("[data-slot=filter-tokens-token]") ||
      target.closest("[data-slot=filter-tokens-clear]") ||
      target.tagName === "INPUT"
    ) {
      return;
    }
    e.preventDefault();
    ft.inputProps.ref.current?.focus();
  }

  return (
    <>
      <div
        data-slot="filter-tokens-announcement"
        role="status"
        aria-live="polite"
        className="sr-only"
      >
        {ft.announcement}
      </div>
      <div
        data-slot="filter-tokens-trigger"
        data-disabled={disabled || undefined}
        className={cn(
          "flex min-h-10 w-full flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-3 py-2 text-sm cursor-text",
          "focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 focus-within:ring-offset-background",
          disabled && "cursor-not-allowed opacity-50",
          className,
        )}
        onMouseDown={handleWrapperMouseDown}
      >
        {ft.tokens.map((token, index) => (
          <Token
            key={token.id}
            ref={(el) => {
              tokenRefs.current[index] = el;
            }}
            category={token.category}
            label={token.label}
            displayValue={token.displayValue}
            ariaLabel={ft.messages.tokenAria(token.label, token.displayValue)}
            removeAriaLabel={ft.messages.tokenRemoveAria(token.label, token.displayValue)}
            onRemove={() => {
              const removeIndex = index;
              const expectedCount = ft.tokens.length - 1;
              token.remove();
              requestAnimationFrame(() => {
                const nextToken =
                  removeIndex < expectedCount
                    ? tokenRefs.current[removeIndex]
                    : null;
                const prevToken =
                  removeIndex > 0
                    ? tokenRefs.current[removeIndex - 1]
                    : null;
                (nextToken ?? prevToken ?? ft.inputProps.ref.current)?.focus();
              });
            }}
            onClick={() => ft.dropdown.openFilter(token.category as keyof T & string)}
            onPrevious={
              index > 0
                ? () => tokenRefs.current[index - 1]?.focus()
                : undefined
            }
            onNext={() => {
              if (index < ft.tokens.length - 1) {
                tokenRefs.current[index + 1]?.focus();
              } else {
                // Last token → step out into the input.
                ft.inputProps.ref.current?.focus();
              }
            }}
            onEscape={() => ft.inputProps.ref.current?.focus()}
            disabled={disabled}
          />
        ))}

        <input
          {...ft.inputProps}
          data-slot="filter-tokens-input"
          disabled={disabled}
          // Panel modes (date / number) render a dialog, not a listbox, so
          // the popup type and the controlled element id both differ.
          aria-haspopup={isPanelMode ? "dialog" : "listbox"}
          aria-controls={
            ft.dropdown.isOpen && !isPanelMode ? listboxId : undefined
          }
          aria-activedescendant={activeDescendantId}
          onClick={() => {
            // Focus alone won't reopen the popover after ESC-from-categories
            // (the input keeps focus, so onFocus doesn't re-fire). A click
            // on the input bar always opens.
            if (!disabled && !ft.dropdown.isOpen) ft.dropdown.open();
          }}
          onKeyDown={(e) => {
            // ArrowLeft on an empty input with the cursor at position 0:
            // step into the token strip, focusing the last token. ArrowRight
            // / typing leaves the input behaviour intact.
            if (
              e.key === "ArrowLeft" &&
              !ft.inputProps.value &&
              ft.tokens.length > 0
            ) {
              const el = e.currentTarget;
              // selectionStart/End are 0 in real browsers and may be null in
              // jsdom for an empty input — both signal "no selection / cursor
              // at the start", which is the only state we step out for.
              const start = el.selectionStart ?? 0;
              const end = el.selectionEnd ?? 0;
              if (start === 0 && end === 0) {
                e.preventDefault();
                tokenRefs.current[ft.tokens.length - 1]?.focus();
                return;
              }
            }
            // Tab is intentionally NOT closed here — letting the natural
            // tab order walk through the popover (back button, retry, etc.)
            // is the only way keyboard-only users can reach those controls.
            // Radix's onFocusOutside still closes the popup once focus
            // genuinely leaves the trigger + content surface.
            ft.inputProps.onKeyDown(e);
          }}
          className="flex-1 min-w-[120px] border-0 bg-transparent p-0 text-sm outline-none placeholder:text-muted-foreground"
        />

        {ft.tokens.length > 0 && (
          <button
            type="button"
            data-slot="filter-tokens-clear"
            tabIndex={-1}
            className="ml-auto shrink-0 rounded-sm p-0.5 text-muted-foreground/60 transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            onMouseDown={(e) => e.stopPropagation()}
            onClick={(e) => {
              e.stopPropagation();
              ft.clear();
              // Don't refocus the input. "Clear all" is a "done" gesture —
              // matching Linear / Notion, the popover stays closed and focus
              // falls naturally. The user clicks the input again if they
              // want to add new filters.
            }}
            aria-label={ft.messages.clearAllAria}
            disabled={disabled}
          >
            <XIcon className="size-4" />
          </button>
        )}
      </div>
    </>
  );
}

"use client";

import * as React from "react";
import { XIcon } from "lucide-react";
import { cn } from "@/lib/utils";

/**
 * Visual rendering of a token (the pill-shaped UI element). Distinct from
 * the `FilterTokensToken` data type — that's the value object (id, category,
 * label, displayValue, remove); this is the visual element rendered inside
 * the trigger.
 */
export interface TokenProps {
  category: string;
  label: string;
  displayValue: string;
  /** Resolved aria-label for the token (`messages.tokenAria`). */
  ariaLabel: string;
  /** Resolved aria-label for the remove button (`messages.tokenRemoveAria`). */
  removeAriaLabel: string;
  onRemove: () => void;
  onClick?: () => void;
  disabled?: boolean;
  /**
   * Move focus to the previous token (ArrowLeft on a focused token).
   * Trigger passes undefined when there is no previous token.
   */
  onPrevious?: () => void;
  /**
   * Move focus to the next token, falling back to the input when this is
   * the last token (ArrowRight on a focused token).
   */
  onNext?: () => void;
  /**
   * Step out of the token strip and back to the input (Escape on a focused
   * token). Aligns with Mantine's tag-input behaviour.
   */
  onEscape?: () => void;
}

export const Token = React.forwardRef<
  HTMLSpanElement,
  TokenProps
>(function Token(
  { category, label, displayValue, ariaLabel, removeAriaLabel, onRemove, onClick, disabled, onPrevious, onNext, onEscape },
  ref,
) {
  return (
    <span
      ref={ref}
      data-slot="filter-tokens-token"
      data-category={category}
      data-disabled={disabled || undefined}
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled || undefined}
      aria-label={ariaLabel}
      className={cn(
        "group inline-flex items-center gap-1 rounded-md bg-secondary py-0.5 pl-2 pr-1 text-xs font-medium text-secondary-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
        disabled
          ? "cursor-not-allowed opacity-50"
          : "cursor-pointer hover:bg-secondary/80",
      )}
      onClick={(e) => {
        e.stopPropagation();
        if (!disabled && onClick) onClick();
      }}
      onMouseDown={(e) => {
        // Prevent the trigger wrapper's mousedown-to-focus-input handler
        // from stealing focus before the token's click runs.
        e.stopPropagation();
      }}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          e.stopPropagation();
          if (!disabled && onClick) onClick();
        } else if (e.key === "ArrowLeft" && onPrevious) {
          e.preventDefault();
          e.stopPropagation();
          onPrevious();
        } else if (e.key === "ArrowRight" && onNext) {
          e.preventDefault();
          e.stopPropagation();
          onNext();
        } else if (e.key === "Backspace" || e.key === "Delete") {
          e.preventDefault();
          e.stopPropagation();
          if (!disabled) onRemove();
        } else if (e.key === "Escape" && onEscape) {
          e.preventDefault();
          e.stopPropagation();
          onEscape();
        }
      }}
    >
      <span
        data-slot="filter-tokens-token-label"
        className="text-muted-foreground"
      >
        {label}:
      </span>
      <span data-slot="filter-tokens-token-value">{displayValue}</span>
      <button
        type="button"
        data-slot="filter-tokens-token-remove"
        tabIndex={-1}
        className="ml-0.5 rounded-sm p-0.5 text-muted-foreground/80 transition-colors hover:bg-secondary-foreground/10 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        onClick={(e) => {
          e.stopPropagation();
          onRemove();
        }}
        onMouseDown={(e) => {
          // Same: don't let the trigger wrapper steal focus to the input
          // before the remove handler runs.
          e.stopPropagation();
        }}
        aria-label={removeAriaLabel}
        disabled={disabled}
      >
        <XIcon className="size-3" />
      </button>
    </span>
  );
});

"use client";

import { CalendarIcon, CheckIcon } from "lucide-react";
import type { FilterTokensDropdownItem } from "filter-tokens";
import { cn } from "@/lib/utils";

export interface ItemIndicatorProps {
  item: FilterTokensDropdownItem;
  isMultiSelect: boolean;
}

export function ItemIndicator({ item, isMultiSelect }: ItemIndicatorProps) {
  if (item.kind === "custom-date") {
    return <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />;
  }

  // Categories and date presets render no leading indicator — categories
  // navigate into a sub-menu, presets apply a value when chosen.
  if (item.kind !== "value") return null;

  if (isMultiSelect) {
    return (
      <div
        className={cn(
          "flex size-4 shrink-0 items-center justify-center rounded-sm border transition-colors",
          item.selected
            ? "border-primary bg-primary text-primary-foreground"
            : "border-input",
        )}
      >
        {item.selected && <CheckIcon className="size-3" />}
      </div>
    );
  }

  return (
    <div
      className={cn(
        "flex size-4 shrink-0 items-center justify-center rounded-full border transition-colors",
        item.selected ? "border-primary" : "border-input",
      )}
    >
      {item.selected && <div className="size-2 rounded-full bg-primary" />}
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronRightIcon, LoaderCircleIcon } from "lucide-react";
import type { FilterSchema, FilterTokensReturn } from "filter-tokens";
import { cn } from "@/lib/utils";
import { ItemIndicator } from "./item-indicator";

export interface ListboxProps<T extends FilterSchema> {
  ft: FilterTokensReturn<T>;
  listboxId: string;
  activeLabel: string | null;
  isMultiSelect: boolean;
  isTextEntry: boolean;
}

export function Listbox<T extends FilterSchema>({
  ft,
  listboxId,
  activeLabel,
  isMultiSelect,
  isTextEntry,
}: ListboxProps<T>) {
  const { items, highlightedIndex, loading, error, retry } = ft.dropdown;
  const showEmpty =
    items.length === 0 && !isTextEntry && !loading && !error;
  const containerRef = React.useRef<HTMLDivElement>(null);

  // Keep the keyboard-highlighted option visible. The listbox has a fixed
  // max-h with overflow-y-auto, so without this, ArrowDown past the visible
  // area moves the highlight off-screen. (jsdom doesn't implement
  // scrollIntoView, so the optional-chain guards the test environment.)
  React.useEffect(() => {
    if (highlightedIndex < 0) return;
    const el = containerRef.current?.querySelector<HTMLElement>(
      '[data-highlighted="true"]',
    );
    el?.scrollIntoView?.({ block: "nearest" });
  }, [highlightedIndex]);

  return (
    <div
      ref={containerRef}
      role="listbox"
      id={listboxId}
      aria-label={activeLabel ?? ft.messages.popupListAria}
      aria-multiselectable={isMultiSelect || undefined}
      aria-orientation="vertical"
      className="max-h-[260px] overflow-y-auto p-1"
    >
      {loading && (
        <div
          data-slot="filter-tokens-loading"
          role="status"
          aria-label={ft.messages.popupLoadingAria}
          className="flex justify-center py-6"
        >
          <LoaderCircleIcon className="size-4 animate-spin text-muted-foreground" />
        </div>
      )}

      {error && !loading && (
        <div
          data-slot="filter-tokens-error"
          role="alert"
          className="flex flex-col items-center gap-2 px-2 py-6 text-center text-sm"
        >
          <span className="text-destructive">{ft.messages.popupErrorLabel}</span>
          <button
            type="button"
            onClick={retry}
            className="rounded-sm text-xs text-muted-foreground underline hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {ft.messages.popupRetryLabel}
          </button>
        </div>
      )}

      {showEmpty && (
        <div
          data-slot="filter-tokens-empty"
          role="status"
          className="px-2 py-6 text-center text-sm text-muted-foreground"
        >
          {ft.messages.popupEmptyLabel}
        </div>
      )}

      {isTextEntry && (
        <div
          data-slot="filter-tokens-text-entry-hint"
          className="px-2 py-3 text-center text-xs text-muted-foreground"
        >
          {ft.messages.popupTextEntryHint}
        </div>
      )}

      {items.map((item, index) => {
        const isHighlighted = index === highlightedIndex;
        return (
          <div
            key={item.key}
            id={`${listboxId}-item-${item.key}`}
            role="option"
            // Categories, presets, and custom-date entries aren't
            // "selectable" in the WAI-ARIA sense — clicking them navigates or
            // applies a value rather than choosing one. Only emit
            // aria-selected for actual value options. The data-selected
            // attribute is preserved either way so consumer CSS can still
            // indicate categories that have an active filter.
            aria-selected={item.kind === 'value' ? item.selected : undefined}
            data-slot="filter-tokens-dropdown-item"
            data-kind={item.kind}
            data-highlighted={isHighlighted || undefined}
            data-selected={item.selected || undefined}
            className={cn(
              "relative flex cursor-pointer select-none items-center gap-2 rounded-md px-2 py-1.5 text-sm outline-none transition-colors",
              isHighlighted
                ? "bg-accent text-accent-foreground"
                : "text-popover-foreground hover:bg-accent/50",
            )}
            onMouseEnter={() => ft.dropdown.setHighlightedIndex(index)}
            onClick={() => ft.dropdown.select(item)}
          >
            <ItemIndicator item={item} isMultiSelect={isMultiSelect} />
            {item.icon && (
              <item.icon className="size-4 shrink-0 text-muted-foreground" />
            )}
            <span className="flex-1 truncate">{item.label}</span>
            {item.kind === "category" && (
              <ChevronRightIcon className="size-3.5 text-muted-foreground/50" />
            )}
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { ChevronLeftIcon } from "lucide-react";
import type { FilterTokensMessages } from "filter-tokens";

export interface HeaderProps {
  activeLabel: string;
  isDateEntry: boolean;
  onBack: () => void;
  messages: FilterTokensMessages;
}

export function Header({ activeLabel, isDateEntry, onBack, messages }: HeaderProps) {
  return (
    <div
      data-slot="filter-tokens-dropdown-header"
      className="flex items-center gap-1.5 border-b border-border px-2 py-1.5"
    >
      <button
        type="button"
        aria-label={
          isDateEntry
            ? messages.popupBackToFilterAria(activeLabel)
            : messages.popupBackAria
        }
        className="rounded-sm p-0.5 text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        onClick={onBack}
      >
        <ChevronLeftIcon className="size-3.5" />
      </button>
      <span className="text-xs font-medium text-muted-foreground">
        {activeLabel}
      </span>
    </div>
  );
}

"use client";

import type { Locale } from "date-fns";
import type {
  FilterSchema,
  FilterTokensReturn,
  FilterValues,
} from "filter-tokens";
import { RangeCalendarPanel, SingleCalendarPanel } from "./calendar-panel";
import { NumberPanel } from "./number-panel";

export interface PanelsProps<T extends FilterSchema> {
  ft: FilterTokensReturn<T>;
  filters: T;
  value: FilterValues<T>;
  dateLocale?: Locale;
}

export function Panels<T extends FilterSchema>({
  ft,
  filters,
  value,
  dateLocale,
}: PanelsProps<T>) {
  const state = ft.dropdown.state;
  if (state.mode !== "input") return null;
  const { category: activeCategory, inputType } = state;

  const activeDef = (filters as FilterSchema)[activeCategory];
  if (!activeDef) return null;

  // Cast through a record once. The hook's generic guarantees the runtime
  // value lives at activeCategory, but the per-branch typing differs.
  const currentValue = (value as Record<string, unknown>)[activeCategory];

  if (inputType === "date" && activeDef.type === "date") {
    return activeDef.range === true ? (
      <RangeCalendarPanel
        showTime={activeDef.time === true}
        locale={dateLocale}
        initialValue={currentValue as { from?: string; to?: string } | undefined}
        onSelect={(v) => ft.applyDate(activeCategory, v)}
        onCancel={ft.dropdown.close}
        messages={ft.messages}
      />
    ) : (
      <SingleCalendarPanel
        showTime={activeDef.time === true}
        locale={dateLocale}
        initialValue={currentValue as { date?: string } | undefined}
        onSelect={(v) => ft.applyDate(activeCategory, v)}
        onCancel={ft.dropdown.close}
        messages={ft.messages}
      />
    );
  }

  if (inputType === "number" && activeDef.type === "number") {
    return (
      <NumberPanel
        unit={activeDef.unit}
        min={activeDef.min}
        max={activeDef.max}
        initialValue={currentValue as { min?: number; max?: number } | undefined}
        onSelect={(v) => ft.applyNumber(activeCategory, v)}
        onCancel={ft.dropdown.close}
        messages={ft.messages}
      />
    );
  }

  return null;
}

