export interface PanelActionsProps {
  /** Whether the Apply button is disabled (no value to commit / invalid range / etc.). */
  applyDisabled?: boolean;
  onCancel: () => void;
  onApply: () => void;
  messages: FilterTokensMessages;
}

/**
 * Cancel + Apply button row shown at the bottom of date and number panels.
 * Single source of truth for spacing, button order, and label wiring so the
 * three panels (range calendar, single calendar, number) stay in sync.
 */
export function PanelActions({
  applyDisabled,
  onCancel,
  onApply,
  messages,
}: PanelActionsProps) {
  return (
    <div className="flex justify-end gap-2 px-3 pb-3">
      <Button variant="ghost" onClick={onCancel}>
        {messages.cancelLabel}
      </Button>
      <Button disabled={applyDisabled} onClick={onApply}>
        {messages.applyLabel}
      </Button>
    </div>
  );
}

"use client";

import * as React from "react";
import type { Locale } from "date-fns";
import type { FilterTokensMessages } from "filter-tokens";
import { Calendar, CalendarDayButton } from "@/components/ui/calendar";
import { DateTimeRow } from "./date-time-row";
import { PanelActions } from "./panel-actions";

/** Returns a copy of the date set to 23:59:59.999 — used to anchor an End
 *  bound to the end of the chosen day instead of midnight at its start. */
function endOfDay(d: Date): Date {
  const out = new Date(d);
  out.setHours(23, 59, 59, 999);
  return out;
}

/** True when the date is at 00:00 — i.e. a calendar-click (which always
 *  produces midnight timestamps) without any user-typed time. */
function isMidnight(d: Date): boolean {
  return d.getHours() === 0 && d.getMinutes() === 0;
}

export interface RangeCalendarPanelProps {
  showTime: boolean;
  locale?: Locale;
  initialValue?: { from?: string; to?: string };
  onSelect: (value: { from?: string; to?: string }) => void;
  onCancel: () => void;
  messages: FilterTokensMessages;
}

export function RangeCalendarPanel({
  showTime,
  locale,
  initialValue,
  onSelect,
  onCancel,
  messages,
}: RangeCalendarPanelProps) {
  const [from, setFrom] = React.useState<Date | undefined>(() =>
    initialValue?.from ? new Date(initialValue.from) : undefined,
  );
  const [to, setTo] = React.useState<Date | undefined>(() =>
    initialValue?.to ? new Date(initialValue.to) : undefined,
  );
  // Open the calendar on whichever side of the range is already set so the
  // existing date is in view. Falls through to today for a fresh range.
  const [month, setMonth] = React.useState<Date>(() => from ?? to ?? new Date());
  // For a fresh range, start with the Start field active; for re-editing an
  // End-only ("Until X") filter, default to the End field so the user can
  // refine without first clicking anywhere.
  const [activeField, setActiveField] = React.useState<"start" | "end">(
    !initialValue?.from && initialValue?.to ? "end" : "start",
  );
  const [hoveredDay, setHoveredDay] = React.useState<Date | undefined>();
  const endInputRef = React.useRef<HTMLInputElement>(null);

  function handleDayClick(day: Date) {
    setHoveredDay(undefined);
    // Calendar clicks produce midnight timestamps — compare dates only
    const dayDate = new Date(day.getFullYear(), day.getMonth(), day.getDate()).getTime();
    const fromDate = from
      ? new Date(from.getFullYear(), from.getMonth(), from.getDate()).getTime()
      : undefined;
    const toDate = to
      ? new Date(to.getFullYear(), to.getMonth(), to.getDate()).getTime()
      : undefined;

    if (activeField === "start") {
      setFrom(day);
      // Only invalidate the existing end if the new start is *after* it.
      // Re-editing the start of an existing range should preserve the end —
      // clearing it on every Start click made the calendar feel destructive.
      if (toDate !== undefined && dayDate > toDate) {
        setTo(undefined);
      }
      setActiveField("end");
    } else {
      if (fromDate !== undefined && dayDate < fromDate) {
        // Clicked before start while End is active: shift start to the clicked
        // day. Keep End active so the user can still pick an end date.
        setFrom(day);
        setTo(undefined);
      } else {
        // Calendar clicks land at midnight; with the time UI visible, default
        // End to the end of that day so a single click implies "all day".
        setTo(showTime && isMidnight(day) ? endOfDay(day) : day);
        setActiveField("start");
      }
    }
  }

  function handleApply() {
    if (!from && !to) return;
    if (from && !to) {
      // Open-ended "Since X"
      onSelect({ from: from.toISOString() });
      return;
    }
    if (!from && to) {
      // Open-ended "Until X"
      onSelect({ to: (showTime ? to : endOfDay(to)).toISOString() });
      return;
    }
    onSelect({
      from: from!.toISOString(),
      to: (showTime ? to! : endOfDay(to!)).toISOString(),
    });
  }

  // Stable DayButton wrapper for hover tracking
  const DayButtonWithHover = React.useMemo(() => {
    return function HoverDayButton(props: React.ComponentProps<typeof CalendarDayButton>) {
      return (
        <CalendarDayButton
          {...props}
          onMouseEnter={() => setHoveredDay(props.day.date)}
        />
      );
    };
  }, []);

  // Build modifiers for range highlighting on single-mode calendar.
  // Covers four cases: nothing set, only Start, only End, both set (real range).
  const rangeModifiers = React.useMemo(() => {
    // Only End is set → highlight End as a single selected day so the user
    // sees the chosen "Until X" date on the calendar. Without this branch
    // the calendar shows no visual feedback at all for End-only filters.
    if (!from && to) {
      return { range_end: [to], selected: [to] };
    }
    if (!from) return {};

    // Show hover preview when End is active
    const previewEnd =
      activeField === "end" && hoveredDay && hoveredDay >= from
        ? hoveredDay
        : undefined;
    const displayEnd = previewEnd ?? to;

    if (!displayEnd || from.getTime() === displayEnd.getTime()) {
      return { range_start: [from], selected: [from] };
    }
    return {
      range_start: [from],
      range_end: [displayEnd],
      range_middle: { after: from, before: displayEnd },
      selected: [from, displayEnd],
    };
  }, [from, to, hoveredDay, activeField]);

  return (
    <div
      data-slot="filter-tokens-calendar"
      className="border-t border-border"
    >
      <div className="space-y-1 px-3 pb-1 pt-3">
        <DateTimeRow
          label={messages.dateFromLabel}
          ariaLabel={messages.dateInputAria(messages.dateFromLabel, showTime)}
          date={from}
          active={activeField === "start"}
          onFocus={() => setActiveField("start")}
          onDateChange={(d) => {
            if (d === undefined) {
              setFrom(undefined);
              return;
            }
            // Trust whatever the user typed. Auto-clearing End when the
            // new Start fell after it was destructive — the user may have
            // been refining Start with End next on the to-do list. The
            // Apply button is disabled when the range is invalid (from >
            // to), giving the user a clear cue without nuking their data.
            setFrom(d);
            setMonth(d);
          }}
          onEnter={() => {
            setActiveField("end");
            endInputRef.current?.focus();
          }}
          showTime={showTime}
          locale={locale}
        />
        <DateTimeRow
          label={messages.dateToLabel}
          ariaLabel={messages.dateInputAria(messages.dateToLabel, showTime)}
          date={to}
          active={activeField === "end"}
          onFocus={() => setActiveField("end")}
          onDateChange={(d) => {
            if (d === undefined) {
              setTo(undefined);
              return;
            }
            // Trust whatever the user typed — even if it's earlier than
            // Start. Auto-swapping to Start was confusing (typed value
            // ended up in a different field). Apply checks for empty,
            // and the consumer can validate range integrity.
            const next = showTime && isMidnight(d) ? endOfDay(d) : d;
            setTo(next);
            setMonth(next);
          }}
          inputRef={endInputRef}
          showTime={showTime}
          locale={locale}
        />
      </div>
      <div className="p-2" onMouseLeave={() => setHoveredDay(undefined)}>
        <Calendar
          className="mx-auto"
          showOutsideDays={false}
          locale={locale}
          month={month}
          onMonthChange={setMonth}
          onDayClick={handleDayClick}
          modifiers={rangeModifiers}
          numberOfMonths={2}
          components={{ DayButton: DayButtonWithHover }}
        />
      </div>
      {/*
        Apply is disabled when the user has nothing to commit OR when the
        typed range is inverted (from > to). The user is free to type Start
        later than End while editing — the disabled state tells them why
        Apply isn't moving forward.
      */}
      <PanelActions
        applyDisabled={(!from && !to) || (from !== undefined && to !== undefined && from > to)}
        onCancel={onCancel}
        onApply={handleApply}
        messages={messages}
      />
    </div>
  );
}

export interface SingleCalendarPanelProps {
  showTime: boolean;
  locale?: Locale;
  initialValue?: { date?: string };
  onSelect: (value: { date: string }) => void;
  onCancel: () => void;
  messages: FilterTokensMessages;
}

export function SingleCalendarPanel({
  showTime,
  locale,
  initialValue,
  onSelect,
  onCancel,
  messages,
}: SingleCalendarPanelProps) {
  const [selected, setSelected] = React.useState<Date | undefined>(() => {
    if (!initialValue?.date) return undefined;
    return new Date(initialValue.date);
  });

  const [month, setMonth] = React.useState<Date>(
    () => selected ?? new Date(),
  );

  function handleApply() {
    if (!selected) return;
    onSelect({ date: selected.toISOString() });
  }

  return (
    <div
      data-slot="filter-tokens-calendar"
      className="border-t border-border"
    >
      <div className="px-3 pb-1 pt-3">
        <DateTimeRow
          label={messages.dateSingleLabel}
          ariaLabel={messages.dateInputAria(messages.dateSingleLabel, showTime)}
          date={selected}
          onDateChange={(d) => {
            setSelected(d);
            if (d) setMonth(d);
          }}
          showTime={showTime}
          locale={locale}
        />
      </div>
      <div className="p-2">
        <Calendar
          mode="single"
          className="mx-auto"
          showOutsideDays={false}
          locale={locale}
          month={month}
          onMonthChange={setMonth}
          selected={selected}
          onSelect={(day) => {
            setSelected(day);
            if (day && !showTime) onSelect({ date: day.toISOString() });
          }}
        />
      </div>
      {showTime && (
        <PanelActions
          applyDisabled={!selected}
          onCancel={onCancel}
          onApply={handleApply}
          messages={messages}
        />
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import type { FilterTokensMessages } from "filter-tokens";
import { cn } from "@/lib/utils";
import { PanelActions } from "./panel-actions";

export interface NumberPanelProps {
  unit?: string;
  min?: number;
  max?: number;
  initialValue?: { min?: number; max?: number };
  onSelect: (value: { min?: number; max?: number }) => void;
  onCancel: () => void;
  messages: FilterTokensMessages;
}

export function NumberPanel({
  unit,
  min,
  max,
  initialValue,
  onSelect,
  onCancel,
  messages,
}: NumberPanelProps) {
  const [minVal, setMinVal] = React.useState(initialValue?.min?.toString() ?? "");
  const [maxVal, setMaxVal] = React.useState(initialValue?.max?.toString() ?? "");
  const minId = React.useId();
  const maxId = React.useId();

  const parsedMin = minVal ? parseFloat(minVal) : undefined;
  const parsedMax = maxVal ? parseFloat(maxVal) : undefined;
  const hasValidMin = parsedMin !== undefined && !isNaN(parsedMin);
  const hasValidMax = parsedMax !== undefined && !isNaN(parsedMax);
  const hasValue = hasValidMin || hasValidMax;

  function handleApply() {
    if (!hasValue) return;
    const result: { min?: number; max?: number } = {};
    if (hasValidMin) result.min = parsedMin;
    if (hasValidMax) result.max = parsedMax;
    onSelect(result);
  }

  return (
    <div
      data-slot="filter-tokens-number"
      className="border-t border-border p-3 space-y-2"
    >
      <div className="flex items-center gap-2 px-2 py-1 text-sm">
        <label htmlFor={minId} className="w-9 shrink-0 text-xs font-medium text-muted-foreground">
          {messages.numberMinLabel}
        </label>
        <input
          id={minId}
          type="number"
          aria-label={messages.numberMinAria(unit)}
          className={cn(
            "flex-1 rounded-md border border-input bg-background px-2.5 py-1.5 text-sm font-mono tabular-nums placeholder:text-muted-foreground/40 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1",
          )}
          placeholder={min !== undefined ? String(min) : ""}
          value={minVal}
          min={min}
          max={max}
          onChange={(e) => setMinVal(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); handleApply(); } }}
        />
        {unit && <span className="text-xs text-muted-foreground">{unit}</span>}
      </div>
      <div className="flex items-center gap-2 px-2 py-1 text-sm">
        <label htmlFor={maxId} className="w-9 shrink-0 text-xs font-medium text-muted-foreground">
          {messages.numberMaxLabel}
        </label>
        <input
          id={maxId}
          type="number"
          aria-label={messages.numberMaxAria(unit)}
          className={cn(
            "flex-1 rounded-md border border-input bg-background px-2.5 py-1.5 text-sm font-mono tabular-nums placeholder:text-muted-foreground/40 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1",
          )}
          placeholder={max !== undefined ? String(max) : ""}
          value={maxVal}
          min={min}
          max={max}
          onChange={(e) => setMaxVal(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); handleApply(); } }}
        />
        {unit && <span className="text-xs text-muted-foreground">{unit}</span>}
      </div>
      <PanelActions
        applyDisabled={!hasValue}
        onCancel={onCancel}
        onApply={handleApply}
        messages={messages}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { format, isValid, parse } from "date-fns";
import { enUS } from "date-fns/locale";
import type { Locale } from "date-fns";
import { cn } from "@/lib/utils";

// Reference date used purely to render the placeholder so the user sees
// what shape the input expects. Year is intentionally far in the past so
// it reads as a sample, not a hint about the active range. The day (15) is
// >12 to be unambiguous between mm/dd and dd/mm conventions.
const PLACEHOLDER_REFERENCE_DATE = new Date(2000, 0, 15, 13, 30);

export interface DateTimeRowProps {
  /** Visible label shown next to the input (e.g. "Start", "End", "Date"). */
  label: string;
  /** Resolved aria-label for the input (typically `messages.dateInputAria(...)`). */
  ariaLabel: string;
  date: Date | undefined;
  /**
   * Called with the parsed date on a successful edit, OR with `undefined`
   * when the user explicitly clears the input. The panel decides whether
   * an undefined value clears just this field or also clears the other
   * end of the range.
   */
  onDateChange: (d: Date | undefined) => void;
  showTime: boolean;
  locale?: Locale;
  active?: boolean;
  onFocus?: () => void;
  onEnter?: () => void;
  inputRef?: React.RefObject<HTMLInputElement | null>;
}

export function DateTimeRow({
  label,
  ariaLabel,
  date,
  onDateChange,
  showTime,
  locale,
  active,
  onFocus,
  onEnter,
  inputRef,
}: DateTimeRowProps) {
  const loc = locale ?? enUS;
  const fmt = showTime ? "P p" : "P";
  const ph = format(PLACEHOLDER_REFERENCE_DATE, fmt, { locale: loc });
  const inputId = React.useId();

  function formatDate(d: Date) {
    return format(d, fmt, { locale: loc });
  }

  function parseInput(v: string): Date | null {
    const t = v.trim();
    if (!t) return null;

    const formats = [fmt, "yyyy-MM-dd HH:mm", "yyyy-MM-dd"];
    for (const f of formats) {
      try {
        const p = parse(t, f, new Date(), { locale: loc });
        if (isValid(p)) return p;
      } catch {
        /* try next format */
      }
    }

    const fallback = new Date(t);
    return isNaN(fallback.getTime()) ? null : fallback;
  }

  const [text, setText] = React.useState(date ? formatDate(date) : "");

  React.useEffect(() => {
    setText(date ? format(date, fmt, { locale: loc }) : "");
  }, [date, fmt, loc]);

  function handleBlur() {
    // Empty input + a previously-set date == "the user wiped this date out".
    // Without this, the input snaps back to the old value and the user can
    // never clear the field once a date has been chosen.
    if (!text.trim()) {
      if (date) onDateChange(undefined);
      return;
    }
    const parsed = parseInput(text);
    if (!parsed) {
      if (date) setText(formatDate(date));
      return;
    }
    if (!date || formatDate(parsed) !== formatDate(date)) {
      onDateChange(parsed);
    }
  }

  return (
    <div
      data-slot="filter-tokens-date-input"
      className="flex items-center gap-2 px-2 py-1 text-sm"
    >
      <label
        htmlFor={inputId}
        className="w-9 shrink-0 text-xs font-medium text-muted-foreground"
      >
        {label}
      </label>
      <input
        id={inputId}
        ref={inputRef}
        type="text"
        aria-label={ariaLabel}
        className={cn(
          "flex-1 rounded-md border bg-background px-2.5 py-1.5 text-sm font-mono tabular-nums placeholder:text-muted-foreground/40 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1",
          active ? "border-ring ring-2 ring-ring ring-offset-1" : "border-input",
        )}
        placeholder={ph}
        value={text}
        onChange={(e) => setText(e.target.value)}
        onFocus={onFocus}
        onBlur={handleBlur}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            e.preventDefault();
            handleBlur();
            onEnter?.();
          }
        }}
      />
    </div>
  );
}
